def sortArray(list): 
    for i in range(len(list)-1):
        minIndex = i 
        for j in range(i+1, len(list)):
            if list[minIndex] > list[j]:
                minIndex = j 
        list[i], list[minIndex] = list[minIndex], list[i]
    return list

